#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"; SCRIPT="$ROOT/scripts/install_baseline_collector.sh"; TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT; fake="$TMP/python3"; printf '#!/bin/sh\nexit 0\n' > "$fake"; chmod +x "$fake"
"$SCRIPT" --python "$fake" --collector "$ROOT/scripts/collect_baseline.py" --managed-dir "$TMP/managed" --merge-receipt-source-host m3 --interval 900 >"$TMP/out"; grep -q 'action=dry-run' "$TMP/out"; grep -q 'merge_receipt_source_host=m3' "$TMP/out"; grep -q "source=$ROOT/scripts/collect_baseline.py" "$TMP/out"; grep -q "managed_collector=$TMP/managed/collect_baseline.py" "$TMP/out"; if "$SCRIPT" --python "$fake" --collector "$ROOT/scripts/collect_baseline.py" --interval 899 >/dev/null 2>&1; then exit 1; fi; grep -q -- '--merge-receipts' "$ROOT/launchd/com.danielraffel.shipyard.baseline-collector.plist.template"; grep -q -- '--merge-receipt-health' "$ROOT/launchd/com.danielraffel.shipyard.baseline-collector.plist.template"; grep -q -- '@MERGE_RECEIPT_SOURCE_HOST_ARGS@' "$ROOT/launchd/com.danielraffel.shipyard.baseline-collector.plist.template"; grep -q -- '@WRAPPER@' "$ROOT/launchd/com.danielraffel.shipyard.baseline-collector.plist.template"; echo "baseline collector installer checks passed"
